begin;
create or replace function private.aios_kernel_authorize_invocation(p_invocation_id uuid) returns public.aios_tool_invocations language plpgsql security definer set search_path='' as $$ declare v public.aios_tool_invocations; c public.aios_contracts; a public.aios_approvals; t public.aios_tools; begin if coalesce(auth.jwt()->>'role','') <> 'service_role' then raise exception 'service-role execution context required' using errcode='42501'; end if; select * into v from public.aios_tool_invocations where id=p_invocation_id for update; if v.id is null then raise exception 'invocation not found'; end if; select * into c from public.aios_contracts where agent_id=v.agent_id and organization_id=v.organization_id and is_active order by version desc limit 1; if c.id is null then raise exception 'no active contract'; end if; select * into t from public.aios_tools where tool_key=v.tool_key; if t.id is null or not t.is_enabled or t.status<>'active' then raise exception 'tool unavailable'; end if; if v.status='requires_approval' then select * into a from public.aios_approvals where id=v.approval_id and invocation_id=v.id for update; if a.id is null or a.status<>'approved' or (a.expires_at is not null and a.expires_at<=now()) then raise exception 'valid approval required'; end if; if a.arguments_hash is distinct from v.arguments_hash or a.approval_version is distinct from c.version or a.tool_key is distinct from v.tool_key then raise exception 'approval no longer matches invocation authorization context'; end if; end if; if v.status not in('approved','requires_approval') then if v.status='executing' then return v; else raise exception 'invocation is not executable: %',v.status; end if; end if; if v.status='requires_approval' then update public.aios_tool_invocations set status='approved',authorization_version=c.version where id=v.id returning * into v; end if; update public.aios_tool_invocations set status='executing',started_at=now(),authorization_version=c.version where id=v.id and status='approved' returning * into v; if v.id is null then raise exception 'invocation was concurrently changed'; end if; return v; end; $$;
create or replace function public.aios_kernel_authorize_invocation(p_invocation_id uuid) returns public.aios_tool_invocations language sql security invoker set search_path='' as $$ select private.aios_kernel_authorize_invocation($1); $$;
create or replace function public.aios_record_evaluation(p_task_id uuid,p_invocation_id uuid,p_correctness numeric,p_completeness numeric,p_policy numeric,p_efficiency numeric,p_execution numeric,p_summary text default null) returns public.aios_evaluations language plpgsql security invoker set search_path='' as $$ begin if coalesce(auth.jwt()->>'role','') <> 'service_role' then raise exception 'service-role execution context required' using errcode='42501'; end if; return private.aios_record_evaluation($1,$2,$3,$4,$5,$6,$7,$8); end; $$;
revoke execute on function public.aios_kernel_authorize_invocation(uuid) from anon,authenticated;
revoke execute on function public.aios_record_evaluation(uuid,uuid,numeric,numeric,numeric,numeric,numeric,text) from anon,authenticated;
commit;
